    # Acount / Sign Off
    def test_EMS1_3472_7014_signOff(self):
        logoutEMS (self)
        logoutTime = datetime.now()
        with assume: assert self.driver.find_element(By.XPATH, "//div[@id=\'login_login_dialog\']/p").text == "Please sign in"
        loginEMS (self, self.emsUsr, self.emsPwd)
        loginTime = datetime.now()
        startTimeRaw = logoutTime - timedelta(seconds = 8)
        endTimeRaw = loginTime + timedelta(seconds = 8)
        dateFormat = "%Y/%m/%d %H:%M:%S"
        startTime = startTimeRaw.strftime(self.dateFormat)
        endTime = endTimeRaw.strftime(self.dateFormat)
        self.driver.find_element(By.LINK_TEXT, "System").click()
        time.sleep(3)
        self.driver.find_element(By.LINK_TEXT, "Security").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "access_log_browse").click()
        time.sleep(3)
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_filter > a").click()
        time.sleep(3)
        self.driver.find_element(By.XPATH, "//*[@id=\"filter_background\"]/div[2]/input[@value=\"Reset\"]").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "accesslog_datepickerFrom_filter").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "accesslog_datepickerFrom_filter").send_keys(startTime)
        self.driver.find_element(By.CSS_SELECTOR, ".ui-datepicker-close").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "accesslog_datepickerTo_filter").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "accesslog_datepickerTo_filter").send_keys(endTime)
        self.driver.find_element(By.CSS_SELECTOR, ".ui-datepicker-close").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "accesslog_query_button").click()
        time.sleep(3)
        descriptionList = ["[Security - user - logout] admin logout from IP " + getLoginIP(), "[Security - user - login] admin login from IP " + getLoginIP()]
        for desc in descriptionList :
            print (desc)
            entryPosition = getPositionByCol(self, "accessLog_table", "Description", desc)
            with assume: assert entryPosition != [-1,-1]

