    # Map / Device / Alarm Status
    def test_EMS1_4369_alarmStatus(self):
        self.driver.find_element(By.LINK_TEXT, "Map").click()
        time.sleep(3)
        self.driver.find_element(By.ID, "navside_icon").click()
        time.sleep(3)
        self.driver.find_element(By.XPATH, "//li[contains(.,\'" + self.dutNodeName + "\')]").click()
        time.sleep(3)
        #Check alarm status
        totalAlarmCount = 0
        for status in range(2, self.alarmStatusCount+1):
            statusAlarmCount = int(self.driver.find_element(By.XPATH, "//div[@id=\'alarmStatus\']/div[" + str(status) + "]/div[2]/a").text)
            totalAlarmCount += statusAlarmCount
        with assume: assert str(totalAlarmCount) == self.driver.find_element(By.XPATH, "//div[@id=\'alarmStatus\']/div[1]/div[2]/a").text
        with assume: assert self.driver.find_element(By.ID, "date_now").text == datetime.now().strftime("%Y-%m-%d")
        self.driver.find_element(By.XPATH, "//div[@id=\'alarmStatus\']/div[1]/div[2]/a").click()
        self.driver.find_element(By.ID, "dashboard_dev_alarm_card_more").click()
        time.sleep(3)
        p= self.driver.window_handles[0]
        c = self.driver.window_handles[1]
        self.driver.switch_to.window(c)
        with assume: assert self.driver.find_element(By.ID, "alarm_activeTable").is_displayed()
        self.driver.close()
        self.driver.switch_to.window(p)
        elementScrolledIntoView(self, self.driver.find_element(By.LINK_TEXT, "Click here for more alarms..."))
        self.driver.find_element(By.LINK_TEXT, "Click here for more alarms...").click()
        match self.browser:
            case "chrome":
                c = self.driver.window_handles[1]
                self.driver.switch_to.window(c)
            case "edge":
                c = self.driver.window_handles[2]
                self.driver.switch_to.window(c)
            case "firefox":
                c = self.driver.window_handles[1]
                self.driver.switch_to.window(c)
        with assume: assert self.driver.find_element(By.ID, "alarm_activeTable").is_displayed()
        #Check the download file
        minTime = datetime.now()
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_export > a").click()
        time.sleep(10)
        maxTime = datetime.now()
        files = glob.glob(os.path.join(self.downloadpath, "*.xls"))
        latestFile = max(files, key=os.path.getmtime)
        latestFileSize = os.path.getsize(latestFile)
        latestFileTimeFloat = os.path.getmtime(latestFile)
        latestFileTime = datetime.fromtimestamp(latestFileTimeFloat)
        with assume: assert latestFileSize > 0
        with assume: assert minTime <= latestFileTime <= maxTime

