    # Maintenance / Schedule / ConfigBackup Immediately
    @pytest.mark.asyncio
    async def test_EMS1_6374_configBackupImmediately(self):
        dateFormat = "%Y-%m-%d_%H:%M:%S"
        self.driver.find_element(By.LINK_TEXT, "Maintenance").click()
        time.sleep(3)
        self.driver.find_element(By.LINK_TEXT, "Schedule").click()
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_create_collector > a").click()
        time.sleep(3)
        Select(self.driver.find_element(By.ID, "schedule_type")).select_by_visible_text("Configuration backup")
        time.sleep(3)
        self.driver.find_element(By.ID, "schedule_name").click()
        exeTime = (datetime.now()).strftime(dateFormat)
        scheduleName = "$py_" + exeTime
        self.driver.find_element(By.ID, "schedule_name").send_keys(scheduleName)
        self.driver.find_element(By.XPATH, "//label[contains(.,\'Immediately\')]").click()
        self.driver.find_element(By.XPATH, "//label[contains(.,\'" + self.dutNodeName + "\')]").location_once_scrolled_into_view
        self.driver.find_element(By.XPATH, "//label[contains(.,\'" + self.dutNodeName + "\')]").click()
        self.driver.find_element(By.XPATH, "//label[contains(.,\'Save config before backup\')]").click()
        self.driver.find_element(By.ID, "schedule_config_backup_save_btn").click()
        time.sleep(90)
        self.driver.find_element(By.CSS_SELECTOR, "#i_action_refresh > a").click()
        entryPosition = getPositionByCol(self, "schedule_table", "Name", scheduleName)
        waitScheduleSuccess (self, entryPosition)
        time.sleep(30)
        #Maintanence table summary assert
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleStatus").text == "Finish"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Name").text == scheduleName
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Type").text == "Config Backup"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleType").text == "Immediately"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").text == "Success"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Times").text == "0"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Timeout").text == "120"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "Deletedays").text == "0"
        with assume: assert getElementByPositionCol(self, "schedule_table", entryPosition , "SaveConfig").text == "Save config before backup"
        scheduleTime = getElementByPositionCol(self, "schedule_table", entryPosition , "ScheduleTime").text.removesuffix(self.timeZone) 
        #Maintanence table detail assert
        getElementByPositionCol(self, "schedule_table", entryPosition , "Modify").click()
        time.sleep(3)
        with assume: assert self.driver.find_element(By.ID, "schedule_type").get_attribute("value") == "maintenance/config_backup"
        with assume: assert self.driver.find_element(By.ID, "schedule_name").get_attribute("value") == scheduleName
        with assume: assert self.driver.find_element(By.ID, "timeout").get_attribute("value") == "120"
        with assume: assert self.driver.find_element(By.ID, "days").get_attribute("value") == "0"
        self.driver.find_element(By.CSS_SELECTOR, ".exit").click()
        #Maintanence table detail 1 assert
        getElementByPositionCol(self, "schedule_table", entryPosition , "Result_Hyperlink").click()
        time.sleep(3)
        self.driver.find_element(By.LINK_TEXT, "Download").click()
        time.sleep(10)
        with assume: assert getScheduleResultByCol (self, "Index") == "1"
        with assume: assert getScheduleResultByCol (self, "Schedule Name") == scheduleName
        dateFormat = "%Y-%m-%d %H:%M:%S"
        minTime = datetime.strptime(scheduleTime, dateFormat)
        maxTime = minTime + timedelta(seconds = 600)
        with assume: assert minTime <= datetime.strptime(getScheduleResultByCol (self, "Execute Time").removesuffix(self.timeZone) , dateFormat) <= maxTime
        resultSummary = getScheduleResultByCol (self, "Result Summary")
