        WebDriverWait(self.driver, 180).until(EC.visibility_of_element_located((By.ID,"index_t_userName")))
        currentTime = datetime.now()
        startTime = currentTime - timedelta(seconds = 10)
        endTime = currentTime + timedelta(seconds = 10)
        entryPosition = getOnlineUsrPosition(self)
        testTimeRaw = getElementByPositionCol(self, "onlineUserTable", entryPosition , "loginTime").text
        testTime = re.sub(r" \(.*$", "",testTimeRaw)
        getTime = datetime.strptime(testTime, self.dateFormat)
        isTimeInRange = (startTime <= getTime <= endTime)
        with assume: assert getElementByPositionCol(self, "onlineUserTable", entryPosition , "userName").text == "PyUser"
        with assume: assert isTimeInRange
        with assume: assert getElementByPositionCol(self, "onlineUserTable", entryPosition , "loginIp").text == getLoginIP()
        getElementByPositionCol(self, "onlineUserTable", entryPosition , "Checkbox").click()
        self.driver.find_element(By.ID, "i_action_delete").click()
        time.sleep (3)
        assert self.driver.find_element(By.ID, "message_text").text == "Can't force logout yourself."
        self.driver.find_element(By.CSS_SELECTOR, "#message_diag .button").click()
        time.sleep (3)
        p = self.driver.window_handles[0]
        c = self.driver.window_handles[1]
        logoutEMS (self)
        self.driver.switch_to.window(p)
        if self.driver.find_element(By.LINK_TEXT, "System").get_attribute("className") == "":
            self.driver.find_element(By.LINK_TEXT, "System").click()
            time.sleep (3)
        if self.driver.find_element(By.LINK_TEXT, "Security").get_attribute("className") == "":
            self.driver.find_element(By.LINK_TEXT, "Security").click()
            time.sleep (3)
        if self.driver.find_element(By.ID, "user_online").get_attribute("className") == "":
            self.driver.find_element(By.ID, "user_online").click()
            time.sleep (3)
        self.driver.find_element(By.ID, "i_action_refresh").click()
        time.sleep (3)
        with assume: assert getPositionByColNext (self, "onlineUserTable", "loginTime", testTimeRaw) == [-1, -1]
        delEMSUsr (self, "PyUser")


