    def test_EMS1_6363_alarmPurgeDownload(self):
        self.driver.find_element(By.LINK_TEXT, "System").click()
        time.sleep (3)
        self.driver.find_element(By.LINK_TEXT, "System Properties").click()
        time.sleep (3)
        self.driver.find_element(By.LINK_TEXT, "System Storage").click()
