        if self.driver.find_element(By.LINK_TEXT, "Alarm Purge").get_attribute("className") == "":
            self.driver.find_element(By.LINK_TEXT, "Alarm Purge").click()
            time.sleep (3)
        self.driver.find_element(By.ID, "Download_button").click()
